mkdir -p scripts; cat > scripts/calc.py <<'E'
import csv,sys
d=sys.argv[1]
def rows(f):
    return list(csv.DictReader(l for l in open(d+'/'+f) if not l.startswith('#')))
u={}
for x in rows('strom_2025.csv'): u[(x['monat'],x['rechnungsnr'])]=int(x['kwh'])
print('Strom eindeutige Monate',len(u),'MWh',sum(u.values())/1000)
print('fehlend',sorted(set('2025-%02d'%m for m in range(1,13))-{k[0] for k in u}))
w={(x['monat'],x['rechnungsnr']):int(x['m3']) for x in rows('wasser_2025.csv')}
print('Wasser Monate',len(w),'m3',sum(w.values()))
E
cd ordner; python3 -I ../../scripts/calc.py . ; cat -n personal_2025.csv | tail -4
